/// The kinds of HDMI register, by the device-tree `reg-names` window
/// each lives in (`enum vc4_hdmi_regs`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[allow(non_camel_case_types)]
pub enum HdmiKind {
    VC4_HDMI,
    VC4_HD,
    VC5_CEC,
    VC5_CSC,
    VC5_DVP,
    VC5_PHY,
    VC5_RAM,
    VC5_RM,
}

impl HdmiKind {
    pub const ALL: [HdmiKind; 8] = [HdmiKind::VC4_HDMI, HdmiKind::VC4_HD, HdmiKind::VC5_CEC, HdmiKind::VC5_CSC, HdmiKind::VC5_DVP, HdmiKind::VC5_PHY, HdmiKind::VC5_RAM, HdmiKind::VC5_RM];

    /// The `reg-names` entry of the window.
    pub fn reg_name(self) -> &'static str {
        match self {
            HdmiKind::VC4_HDMI => "hdmi",
            HdmiKind::VC4_HD => "hd",
            HdmiKind::VC5_CEC => "cec",
            HdmiKind::VC5_CSC => "csc",
            HdmiKind::VC5_DVP => "dvp",
            HdmiKind::VC5_PHY => "phy",
            HdmiKind::VC5_RAM => "packet",
            HdmiKind::VC5_RM => "rm",
        }
    }
}

